# =============================================================================
# benchmarks/run_all.R - run the 5 comparisons and collect the theory-vs-observed notes
#
#   Rscript benchmarks/run_all.R                 # everything (full sizes; ~tens of minutes)
#   Rscript benchmarks/run_all.R quick           # smoke test with tiny sizes
#   Rscript benchmarks/run_all.R 05 08           # only some experiments (05-09)
#
# Results: benchmarks/results/*.csv and *.png, and benchmarks/results/notes.rds
# (theory-vs-observation text generated by benchmarks/notes.R from the CSVs; used by
# the report).
# =============================================================================
args <- commandArgs(TRUE)
quick <- "quick" %in% args
sel <- setdiff(args, "quick")

source("benchmarks/common.R")
source("benchmarks/exp_np_hard.R")
source("benchmarks/exp_other.R")

experiments <- list(
  "05" = exp05_tsp, "06" = exp06_setcover, "07" = exp07_vertexcover, "08" = exp08_karger, "09" = exp09_quicksort)
if (length(sel) > 0L) experiments <- experiments[names(experiments) %in% sel]

notes_path <- file.path(RESULTS_DIR, if (quick) "notes_quick.rds" else "notes.rds")
notes <- if (file.exists(notes_path)) readRDS(notes_path) else list()
for (id in names(experiments)) {
  t0 <- proc.time()[["elapsed"]]
  cat(sprintf("\n=== experiment %s ===\n", id)); flush.console()
  res <- experiments[[id]](quick = quick)
  notes[[id]] <- res$notes
  saveRDS(notes, notes_path)
  cat(sprintf("done in %.0f s\n%s\n", proc.time()[["elapsed"]] - t0, res$notes))
}
cat("\nAll requested benchmarks finished.\n")
